// Bit strings and their variation.
//
// The space is the hypercube {0,1}ⁿ, a Cayley graph of the group (ℤ/2)ⁿ generated by the unit vectors; its
// symmetry group is the hyperoctahedral group (ℤ/2)ⁿ ⋊ Sₙ, translations x ↦ x ⊕ m and permutations of the
// positions. Standard bit mutation (each bit flipped independently with probability p) commutes with the whole
// group; so does uniform crossover (generic.hpp).
//
// Mutations, each returning the number of bits it flipped:
// - standard bit mutation, by geometric jumps between flipped positions, O(pn) draws (each gap is the number
//   of failures before a success; Devroye 1986, Non-Uniform Random Variate Generation, §X.2);
// - the same conditioned on flipping at least one bit, the "shift" or ">0" variant, which never wastes an
//   evaluation on a copy (Carvalho Pinto and Doerr 2018, "A simple proof for the usefulness of crossover in
//   black-box optimization", PPSN, and Doerr and Neumann 2020, Theory of Evolutionary Computation, ch. 1): the
//   number of flips is a binomial conditioned on ≥ 1, the positions a uniform subset of that size;
// - exactly k distinct bits (randomised local search, k = 1);
// - heavy-tailed mutation, fmut_β (Doerr, Le, Makhmara and Nguyen 2017, "Fast genetic algorithms", GECCO,
//   §3): the rate α/n with α ∈ {1, …, ⌊n/2⌋} drawn with probability α^{−β}/C_β, so that large jumps occur with
//   polynomially, not exponentially, small probability; on Jump_k it is faster than any fixed rate by a factor
//   k^{Θ(k)} (their Theorem 7).

#pragma once

#include <calx/random/stream.hpp>

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <stdexcept>
#include <vector>

namespace heuresis::variation {

using Bits = std::vector<std::uint8_t>;  // each entry 0 or 1

inline Bits random_bits(std::size_t n, calx::random::Stream& s) {
  Bits x(n);
  for (std::size_t i = 0; i < n; i += 32) {
    std::uint32_t w = s.next32();
    for (std::size_t j = i; j < std::min(n, i + 32); j++, w >>= 1) x[j] = w & 1u;
  }
  return x;
}

inline std::size_t ones(const Bits& x) {
  std::size_t k = 0;
  for (auto b : x) k += b;
  return k;
}

// Flips each bit with probability p; returns the number flipped.
inline std::size_t standard_bit_mutation(Bits& x, double p, calx::random::Stream& s) {
  if (!(p > 0)) return 0;
  if (p >= 1) {
    for (auto& b : x) b ^= 1u;
    return x.size();
  }
  std::size_t flipped = 0;
  for (std::uint64_t i = s.geometric(p); i < x.size(); i += 1 + s.geometric(p)) {
    x[i] ^= 1u;
    flipped++;
  }
  return flipped;
}

// Flips k distinct bits, chosen uniformly (Floyd's sampling); returns k.
inline std::size_t flip_exactly(Bits& x, std::size_t k, calx::random::Stream& s) {
  const std::size_t n = x.size();
  if (k > n) throw std::invalid_argument("heuresis::variation::flip_exactly: more flips than bits");
  if (2 * k > n) {  // flip all, then unflip n − k
    for (auto& b : x) b ^= 1u;
    flip_exactly(x, n - k, s);
    return k;
  }
  std::vector<std::size_t> chosen;
  chosen.reserve(k);
  for (std::size_t j = n - k; j < n; j++) {
    const std::size_t t = s.below(j + 1);
    if (std::find(chosen.begin(), chosen.end(), t) == chosen.end()) chosen.push_back(t);
    else chosen.push_back(j);
  }
  for (auto i : chosen) x[i] ^= 1u;
  return k;
}

// Standard bit mutation conditioned on flipping at least one bit.
inline std::size_t standard_bit_mutation_positive(Bits& x, double p, calx::random::Stream& s) {
  if (x.empty()) return 0;
  std::int64_t l = 0;
  if (p >= 1) l = static_cast<std::int64_t>(x.size());
  else
    while (l == 0) l = s.binomial(static_cast<std::int64_t>(x.size()), p);
  return flip_exactly(x, static_cast<std::size_t>(l), s);
}

// The power law of fmut_β on {1, …, ⌊n/2⌋}.
class PowerLaw {
 public:
  PowerLaw(std::size_t n, double beta) : n_(n) {
    if (!(beta > 1)) throw std::invalid_argument("heuresis::variation::PowerLaw: β must exceed 1");
    const std::size_t m = std::max<std::size_t>(1, n / 2);
    cumulative_.resize(m);
    double c = 0;
    for (std::size_t a = 1; a <= m; a++) cumulative_[a - 1] = (c += std::pow(static_cast<double>(a), -beta));
    for (auto& v : cumulative_) v /= c;
  }
  std::size_t draw(calx::random::Stream& s) const {
    const double u = s.uniform();
    return 1 + static_cast<std::size_t>(std::lower_bound(cumulative_.begin(), cumulative_.end(), u) - cumulative_.begin());
  }
  double probability(std::size_t a) const { return a == 0 || a > cumulative_.size() ? 0 : cumulative_[a - 1] - (a > 1 ? cumulative_[a - 2] : 0); }
  std::size_t n() const { return n_; }

 private:
  std::size_t n_;
  std::vector<double> cumulative_;
};

// fmut_β: a rate α/n with α from the power law, then standard bit mutation at that rate.
inline std::size_t heavy_tailed_mutation(Bits& x, const PowerLaw& law, calx::random::Stream& s) {
  const double alpha = static_cast<double>(law.draw(s));
  return standard_bit_mutation(x, alpha / static_cast<double>(x.size()), s);
}

}  // namespace heuresis::variation
